import{C as r,j as e,S as a}from"./index-DNviO348.js";import{L as c}from"./react-vendor-AIXwcq2c.js";const{interviews:o,fromYear:s,toYear:i}=r,d=[{q:"What is Altovisas?",a:`Altovisas is a free practice tool for the United States F-1 student visa interview. You describe your profile and answer interview questions, and it returns an automated read of where a consular officer is most likely to push back on a case like yours. It is built on ${o.toLocaleString()} interview reports written by applicants about their own interviews between ${s} and ${i}.`},{q:"How does it work?",a:"You give a short profile - university, programme, funding, consulate - and answer three interview questions in your own words. Your answers are compared against the interview reports in the dataset, and you get back the specific points an officer is most likely to probe, along with the numbers behind each one. It takes about four minutes and needs a free account."},{q:"Is it free?",a:"Yes. The profile check is free. It needs a free account, which keeps your rounds and progress, but never a credit card. The statistics on the home page are open to everyone without one."},{q:"Where does the interview data come from?",a:`The dataset is ${o.toLocaleString()} accounts of F-1 visa interviews from ${s} to ${i}, written by applicants about their own interviews and posted publicly online, then de-duplicated and parsed question by question. Roughly 200 more are added each month.`},{q:"Can Altovisas predict whether my visa will be approved?",a:"No, and no tool can. The dataset is self-selected and self-reported: approval shares in it describe who chose to write something down, not the true approval rate at any consulate. Associations in the data are correlational, not causal. Nothing on the site predicts an individual outcome, and a visa decision is made solely by a consular officer."},{q:"What questions do officers ask at an F-1 interview?",a:"The most common areas in the dataset are how the degree is funded and who is sponsoring it, the sponsor's occupation and income, which other universities you applied to, your undergraduate background and grades, why this university and this course, and what you plan to do after the degree. The mix varies noticeably by consulate."},{q:"How long does the interview last?",a:"Most reports in the dataset describe an exchange of four or five questions lasting two to three minutes at the window. The brevity is why preparation tends to focus on the first answer to each topic rather than on long explanations."},{q:"What documents should I bring?",a:"Requirements are set by the consulate, not by us, and they change. Check the instructions for your own consulate on travel.state.gov and any guidance from your designated school official. Applicants commonly report carrying their I-20, DS-160 confirmation, SEVIS fee receipt, passport, admission letter, and financial documents."},{q:"Should I memorise the answers Altovisas suggests?",a:"No. Suggestions are about structure - what to lead with, what to leave out, how much detail to give. The facts inside an answer must be your own and must be true. Misrepresenting a material fact to a consular officer carries consequences that can last a lifetime."},{q:"Is this legal or immigration advice?",a:"No. Altovisas is a practice tool, not a law firm, and it is not affiliated with the U.S. Department of State, any embassy or consulate, or any other government body. For advice about your own case, consult a licensed immigration attorney."},{q:"Is my data secure?",a:"Your profile and answers are private to your account, are never shown to other users, and are not sold or published. You can have everything deleted by emailing us. The Privacy Policy sets out what is collected, who processes it, and how long it is kept."},{q:"Can I practise more than once?",a:"Yes. You can run the profile check on more than one set of answers, and a short survey unlocks additional sets."}];function u(){return e.jsx("div",{className:"tf",children:e.jsxs("article",{className:"page-w doc",children:[e.jsx("h1",{children:"F-1 visa interview questions"}),e.jsx("p",{className:"lede",children:"What officers ask, how the data behind Altovisas was built, and what it can and cannot tell you."}),e.jsx("div",{className:"doc-qa",children:d.map(({q:t,a:n})=>e.jsxs("section",{children:[e.jsx("h2",{children:t}),e.jsx("p",{children:n})]},t))}),e.jsxs("section",{className:"doc-end",children:[e.jsx("h2",{children:"Still have a question?"}),e.jsxs("p",{children:["Email ",e.jsx("a",{href:`mailto:${a.contact}`,children:a.contact}),", or read"," ",e.jsx(c,{to:"/about",children:"how Altovisas works"}),"."]})]})]})})}export{u as default};
